# seed mask demo2; enumerate all translated occurrences whose mask cells are zeros in input
seed=[(r-11,c-15) for r in range(11,15) for c in range(15,18) if a[r][c]==8]
print(seed)
def occ_union(arr, mask, rotations=False):
 R,C=len(arr),len(arr[0]); placements=[]
 # exact translation
 for r0 in range(R):
  for c0 in range(C):
   if all(0<=r0+dr<R and 0<=c0+dc<C and arr[r0+dr][c0+dc]==0 for dr,dc in mask):
    placements.append([(r0+dr,c0+dc) for dr,dc in mask])
 return placements
p=occ_union(a,seed)
u={(r,c) for p0 in p for r,c in p0}
expected={(r,c) for r in range(len(a)) for c in range(len(a[0])) if b[r][c]==8}
print('placements',len(p),'union',len(u),'expected',len(expected),'extra',len(expected-u),'miss',len(u-expected))
